import os
import six
import logging
from moler.device import DeviceFactory
from moler.exceptions import CommandFailure
from taf.ul.moler.converter.interface import get_devices_from_regex
from taf.rfrl.bts.devices.du.logs_collecting.basic_logs import GenericLog
from taf.rfrl.bts.helpers.singleton import Singleton
from taf.rfrl.bts.devices.exceptions import LMINotConfigured
from taf.rfrl.utilities import tl_config
from taf.rfrl.utilities.robot.general import set_robot_suite_variable
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.test_config import get_log_path


class GenericRuBtslogCollector(GenericLog):
    """Logs collecting keywords for RU"""

    def setup_ru_btslog_collector_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Setup RU BtsLog collector for all RUs - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        """
        all_radios = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.setup_ru_btslog_collector(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU btslog startup due to LMI not configured for syslog, Details: {e}")

    def start_collecting_ru_btslog_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Start collecting RU btslog for all RUs - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        """
        all_radios = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.start_collecting_ru_btslog(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU btslog collecting due to LMI not configured for syslog, Details: {e}")

    def stop_collecting_ru_btslog_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Stop collecting RU btslog for all RUs - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        """
        all_radios = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.stop_collecting_ru_btslog(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU btslog stop due to LMI not configured for syslog, Details: {e}")

    def teardown_ru_btslog_collector_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Teardown RU BtsLog collector for all RUs - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        """
        all_radios = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.teardown_ru_btslog_collector(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU btslog teardown due to LMI not configured for syslog, Details: {e}")

    @load_moler_configuration_from_tl()
    def setup_ru_btslog_collector(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                                  target_file_name=None):
        """
        Setup RU BtsLog collector - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id: RU id - related to Test Line configuration
        :param common_unit_id: Id of CommonUnit
        :param capacity_unit_id: Id of CapacityUnit
        :param target_file_name: file_name.tgz format, its part of the path under which syslog file
                                 stored locally during collect_collectors

        :return:
        """
        ru = tl_config.get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        if ru.lmi is None or ru.lmp_connection is None:
            raise LMINotConfigured(f"LMI or RU lmp connection is not configured to collect syslog for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")
        if not target_file_name:
            target_file_name = f'{self.bts_type}{bts_id}_DU{du_id}_RU{ru_id}_syslog_files.tgz'
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        btslog = self._try_to_get_robot_builtin_instance('btslog', 'taf.collectors.btslog')
        name = f"btslog_{self.bts_type}{bts_id}_DU{du_id}_RU{ru_id}_{ru.serial_number}"
        ws_credentials = tl_config.get_ru_ws_credentials(bts_id, du_id, ru_id, self.bts_type,
                                                         common_unit_id, capacity_unit_id)
        bts_collector = self.try_to_get_alias_value(alias=name)

        if not bts_collector:
            self._kill_all_ru_btslog_processes(ru_id=ru_id)
            btslog.create_btslog_collector(name=name, executor=ws_credentials, target_file_name=target_file_name,
                                           start_timeout=30)
            btslog.set_suite_alias(alias=name)
            core.setup_collectors(names=name)
        else:
            logging.debug("BtsLog RU collector with name {} already exist. Skipping setup procedure".format(name))

    def start_collecting_ru_btslog(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None):
        """
        Start collecting RU btslog - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id: RU id - related to Test Line configuration
        :param common_unit_id: Id of CommonUnit
        :param capacity_unit_id: Id of CapacityUnit
        :return:
        """
        ru = tl_config.get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        if ru.lmi is None or ru.lmp_connection is None:
            raise LMINotConfigured(f"LMI or RU lmp connection is not configured to collect syslog for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        name = f"btslog_{self.bts_type}{bts_id}_DU{du_id}_RU{ru_id}_{ru.serial_number}"
        btslog_collector = self.try_to_get_alias_value(alias=name)
        if not btslog_collector:
            self.setup_ru_btslog_collector(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)
        elif btslog_collector._is_started:
            logging.debug("RU BtsLog for {} is already started. Skipping starting procedure".format(name))
            return
        try:
            core.start_collectors(names=name)
        except Exception as e:
            logging.warning(repr(e))
            logging.debug("try to setup and start ru btslog again")
            self.teardown_ru_btslog_collector(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            self.setup_ru_btslog_collector(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)
            core.start_collectors(names=name)

    @load_moler_configuration_from_tl()
    def stop_collecting_ru_btslog(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                                  log_dir=None, file_prefix=None):
        """
        Stop collecting RU btslog - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id: RU id - related to Test Line configuration
        :param common_unit_id: Id of CommonUnit
        :param capacity_unit_id: Id of CapacityUnit
        :param log_dir: Directory where btslog will be collected
        :param file_prefix: By default syslog files are packed and keep in tgz file with static name
                            To avoid overwrite this file, please use unique prefix.
        :return:
        """
        ru = tl_config.get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        if ru.lmi is None or ru.lmp_connection is None:
            raise LMINotConfigured(f"LMI or RU lmp connection is not configured to collect syslog for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        name = f"btslog_{self.bts_type}{bts_id}_DU{du_id}_RU{ru_id}_{ru.serial_number}"

        btslog_collector = self.try_to_get_alias_value(alias=name)
        if btslog_collector and not btslog_collector._is_started:
            logging.debug("RU BtsLog for {} is not started. Skipping stopping procedure".format(name))
            return

        if log_dir is None:
            log_dir = f"{get_log_path()}/RMOD"
        try:
            core.stop_collectors(names=name)
        except Exception as e:
            logging.info(repr(e))
            btslog_collector._is_started = False

        core.collect_collectors(names=name, target_dir=log_dir)
        syslog_path = os.path.join(log_dir, name, btslog_collector._target_file_name)
        unix_local = DeviceFactory.get_device(name='UnixLocal')
        if file_prefix:
            source_file = syslog_path
            syslog_path = os.path.join(log_dir, name, "{}_{}".format(file_prefix,
                                                                     btslog_collector._target_file_name))
            change_name = unix_local.get_cmd(cmd_name='mv',
                                             cmd_params={'src': "'{}'".format(source_file),
                                                         'dst': "'{}'".format(syslog_path)})
            change_name()

        logs_to_remove = os.path.join(btslog_collector._log_dir, "SYSLOG_*")
        ru_ws_name = get_devices_from_regex(pattern=self.ws_ru_pattern.format(ru_id))[0]
        ru_ws_device = DeviceFactory.get_device(name=ru_ws_name)
        rm_old_logs = ru_ws_device.get_cmd(cmd_name='rm',
                                           cmd_params={'file': logs_to_remove,
                                                       'options': '-rf'})
        try:
            rm_old_logs()
        except CommandFailure as e:
            logging.debug("Cannot clear logs dir {}. {}".format(logs_to_remove, repr(e)))

        return syslog_path

    def teardown_ru_btslog_collector(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None):
        """
        Teardown btslog collector - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id: RU id - related to Test Line configuration
        :param common_unit_id: Id of CommonUnit
        :param capacity_unit_id: Id of CapacityUnit
        :return:
        """
        ru = tl_config.get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        if ru.lmi is None or ru.lmp_connection is None:
            raise LMINotConfigured(f"LMI or RU lmp connection is not configured to collect syslog for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        name = f"btslog_{self.bts_type}{bts_id}_DU{du_id}_RU{ru_id}_{ru.serial_number}"

        core.teardown_collectors(names=name)
        set_robot_suite_variable('collectors::{}'.format(name), None)

    def _kill_all_ru_btslog_processes(self, ru_id=0):
        ru_ws_name = get_devices_from_regex(pattern=self.ws_ru_pattern.format(ru_id))[0]
        ru_ws_device = DeviceFactory.get_device(name=ru_ws_name)
        kill_btslog = ru_ws_device.get_cmd(cmd_name='pkill',
                                           cmd_params={'name': 'btslog'})
        kill_btslog()

    def try_to_get_alias_value(self, alias):
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        try:
            all_collector_aliases = core._get_all_alias_from_collector_namespace()
            alias_value = all_collector_aliases.get(alias)
        except RuntimeError:
            alias_value = None
        return alias_value


@six.add_metaclass(Singleton)
class EnbRuBtslogCollector(GenericRuBtslogCollector):
    """Class contains RU logs collecting keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """

        super(EnbRuBtslogCollector, self).__init__(bts_type=EnbRuBtslogCollector.bts_type)


@six.add_metaclass(Singleton)
class GnbRuBtslogCollector(GenericRuBtslogCollector):
    """Class contains RU btslog collecting keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.

        """
        super(GnbRuBtslogCollector, self).__init__(bts_type=GnbRuBtslogCollector.bts_type)
